let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const id = input.documentId;
const timestamp = input.timestamp;
const title = input.title;
const key = input.idempotencyKey;
const vendorStatus = input.vendorStatus ?? 200;
const headers = { "content-type": "application/json" };

const out = (o) => console.log(JSON.stringify(o));
const document = { id, title, createdAt: timestamp };

const replay = input.replay === true || input.replayed === true || input.existing != null || input.previous != null;

if (replay) {
  const prior = input.existing ?? input.previous ?? document;
  const body = { id: prior.id ?? id, title: prior.title ?? title, createdAt: prior.createdAt ?? timestamp };
  out({
    http: { status: 200, headers: { ...headers, "idempotent-replay": "true" }, body },
    database: { rows: [], transaction: { committed: false, rolledBack: false } },
    messages: [],
    outbound: [],
    ordering: [],
    failures: [],
    retryability: false
  });
} else if (!title || typeof title !== "string" || !id) {
  out({
    http: { status: 400, headers, body: { error: "invalid_request" } },
    database: { rows: [], transaction: { committed: false, rolledBack: true } },
    messages: [],
    outbound: [],
    ordering: [],
    failures: [{ type: "validation", status: 400 }],
    retryability: false
  });
} else if (vendorStatus >= 200 && vendorStatus < 300) {
  const outbound = [
    { vendor: "authorize", documentId: id, idempotencyKey: key, status: vendorStatus },
    { vendor: "index", documentId: id, idempotencyKey: key, status: vendorStatus }
  ];
  out({
    http: { status: 201, headers, body: document },
    database: { rows: [{ ...document, idempotencyKey: key }], transaction: { committed: true, rolledBack: false } },
    messages: [{ type: "document.created", documentId: id, occurredAt: timestamp, idempotencyKey: key }],
    outbound,
    ordering: ["vendor.authorize", "vendor.index", "database.commit", "message.document.created"],
    failures: [],
    retryability: false
  });
} else {
  const retryable = vendorStatus === 408 || vendorStatus === 429 || vendorStatus >= 500;
  const status = vendorStatus === 401 || vendorStatus === 403 ? 502 : retryable ? 503 : 502;
  out({
    http: { status, headers, body: { error: "vendor_failure" } },
    database: { rows: [], transaction: { committed: false, rolledBack: true } },
    messages: [],
    outbound: [{ vendor: "authorize", documentId: id, idempotencyKey: key, status: vendorStatus }],
    ordering: ["vendor.authorize", "database.rollback"],
    failures: [{ type: "vendor", vendorStatus, status }],
    retryability: retryable
  });
}

